pragma solidity >=0.8.0;

contract RuntimeInt16Div {
    int16 public last;
    int16 public lastMod;
    uint256 public count;

    function divArgs(int16 a, int16 b) external returns (int16) {
        int16 x = a / b;
        last = x;
        count += 1;
        return x;
    }

    function modArgs(int16 a, int16 b) external returns (int16) {
        int16 x = a % b;
        lastMod = x;
        count += 1;
        return x;
    }

    function safeDiv(int16 a, int16 b) external returns (int16) {
        int16 x = a / b;
        last = x;
        count += 1;
        return x;
    }
}
